fn wall(rows_y: i32, x: i32) -> i32 {
    (rows_y >> x) % 2
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let cs: i32 = w / 8;
    let rows = [255, 145, 215, 129, 189, 133, 145, 255];
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 1);
        host::display::state_set(2, 1);
        host::display::state_set(3, 0);
        host::display::state_set(4, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(5) == 0;
    host::display::state_set(5, down);
    let mut px: i32 = host::display::state_get(1);
    let mut py: i32 = host::display::state_get(2);
    if host::display::state_get(4) == 1 {
        host::display::clear(0x041804);
        host::display::draw_string(160, 180, "ESCAPED", 0x00ff88, 4);
        host::display::draw_string(150, 250, "STEPS", 0x808080, 2);
        host::display::draw_number(260, 244, host::display::state_get(3), 0xffffff, 3);
        host::display::draw_string(140, 320, "TAP TO RE-ENTER", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        if tap {
            let mut dx: i32 = host::display::pointer_x() - (px * cs + cs / 2);
            let mut dy: i32 = host::display::pointer_y() - (py * cs + cs / 2);
            let mut ax: i32 = dx;
            if ax < 0 { ax = -ax; }
            let mut ay: i32 = dy;
            if ay < 0 { ay = -ay; }
            let mut nx: i32 = px;
            let mut ny: i32 = py;
            if ax > ay {
                if dx > 0 { nx = px + 1; } else { nx = px - 1; }
            } else {
                if dy > 0 { ny = py + 1; } else { ny = py - 1; }
            }
            if wall(rows[ny], nx) == 0 {
                px = nx;
                py = ny;
                host::display::state_set(1, px);
                host::display::state_set(2, py);
                host::display::state_set(3, host::display::state_get(3) + 1);
            }
            if px == 6 && py == 6 {
                host::display::state_set(4, 1);
            }
        }
        host::display::clear(0x101418);
        let mut y: i32 = 0;
        while y < 8 {
            let mut x: i32 = 0;
            while x < 8 {
                if wall(rows[y], x) == 1 {
                    host::display::fill_rect(x * cs, y * cs, cs, cs, 0x304050);
                }
                x = x + 1;
            }
            y = y + 1;
        }
        host::display::fill_rect(6 * cs + 8, 6 * cs + 8, cs - 16, cs - 16, 0x00aa44);
        host::display::fill_rect(px * cs + 12, py * cs + 12, cs - 24, cs - 24, 0xffdd00);
        host::display::draw_number(8, 4, host::display::state_get(3), 0xffffff, 2);
    }
    host::display::present();
}
